#!/usr/bin/env node
// Assemble the `bundle` release branch from the backend, frontend, and cli branches.
//
//   node scripts/build-bundle.mjs           # assemble + commit locally
//   node scripts/build-bundle.mjs --push    # ...and push bundle + main
//
// Zero dependencies. Safe to re-run: a second run with no upstream changes is a no-op.

import { spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const BUNDLE = join(ROOT, 'bundle');
const PUSH = process.argv.includes('--push');

// npm is a .cmd shim on Windows, which spawn() can't exec without a shell.
const IS_WINDOWS = process.platform === 'win32';

function log(message) {
  console.log(`\n\u001b[1m→ ${message}\u001b[0m`);
}

function run(command, args, { cwd = ROOT, shell = false } = {}) {
  const result = spawnSync(command, args, { cwd, stdio: 'inherit', shell });

  if (result.error) {
    throw new Error(`failed to launch ${command}: ${result.error.message}`);
  }
  if (result.status !== 0) {
    throw new Error(`${command} ${args.join(' ')} exited with code ${result.status}`);
  }
}

/** True when the index holds changes — i.e. `git commit` won't fail on an empty stage. */
function hasStagedChanges(cwd) {
  const { status } = spawnSync('git', ['diff', '--cached', '--quiet'], { cwd });
  return status === 1;
}

/**
 * True when local HEAD differs from the remote branch tip, so pushing has work to do.
 * Decoupled from "did we just commit?" — an earlier run may have committed without
 * pushing (or a CI run may have died in between), and those commits must still ship.
 */
function needsPush(cwd, branch) {
  const local = capture('git', ['rev-parse', 'HEAD'], { cwd });
  const remote = capture('git', ['rev-parse', `origin/${branch}`], { cwd });
  return local !== '' && local !== remote;
}

function capture(command, args, { cwd = ROOT } = {}) {
  const result = spawnSync(command, args, { cwd, encoding: 'utf8' });
  return result.status === 0 ? (result.stdout || '').trim() : '';
}

const NPM = IS_WINDOWS ? { cmd: 'npm.cmd', shell: true } : { cmd: 'npm', shell: false };

// ---------------------------------------------------------------------------

function updateSubmodules() {
  log('Updating source submodules to their branch tips');
  run('git', ['submodule', 'update', '--init', '--remote', 'backend', 'frontend', 'cli']);
}

function buildFrontend() {
  log('Building the frontend');
  const frontend = join(ROOT, 'frontend');

  run(NPM.cmd, ['install'], { cwd: frontend, shell: NPM.shell });
  run(NPM.cmd, ['run', 'build'], { cwd: frontend, shell: NPM.shell });

  const browserDir = join(frontend, 'dist', 'snip-frontend', 'browser');
  if (!existsSync(join(browserDir, 'index.html'))) {
    throw new Error(
      `frontend build produced no ${join(browserDir, 'index.html')}\n` +
        '  The Angular project must stay named "snip-frontend" — the bundle copies\n' +
        '  from dist/snip-frontend/browser.'
    );
  }
  return browserDir;
}

function assemble(browserDir) {
  log('Assembling bundle/');

  if (!existsSync(BUNDLE)) {
    throw new Error('bundle/ is missing — run: git submodule update --init bundle');
  }

  // The two source files travel as-is.
  cpSync(join(ROOT, 'backend', 'server.js'), join(BUNDLE, 'server.js'));
  cpSync(join(ROOT, 'cli', 'cli.js'), join(BUNDLE, 'cli.js'));

  // Replace public/ wholesale so removed assets don't linger between builds.
  const publicDir = join(BUNDLE, 'public');
  rmSync(publicDir, { recursive: true, force: true });
  mkdirSync(publicDir, { recursive: true });
  cpSync(browserDir, publicDir, { recursive: true });

  // Bun auto-loads .env, flipping the server into also-serve-the-UI mode.
  writeFileSync(join(BUNDLE, '.env'), 'PUBLIC_DIR=./public\n');

  // No "type" field: cli.js is CommonJS and must still run under plain node.
  writeFileSync(
    join(BUNDLE, 'package.json'),
    JSON.stringify(
      {
        name: 'snip-bundle',
        version: '1.0.0',
        description: 'Snip — generated release bundle (API + web UI + CLI).',
        private: true,
        scripts: { start: 'bun server.js' },
        bin: { snip: 'cli.js' },
      },
      null,
      2
    ) + '\n'
  );

  writeFileSync(
    join(BUNDLE, 'Dockerfile'),
    [
      '# Generated by scripts/build-bundle.mjs — do not hand-edit.',
      'FROM oven/bun:1-alpine',
      'WORKDIR /app',
      'COPY . .',
      'ENV PORT=3000',
      'EXPOSE 3000',
      'CMD ["bun", "server.js"]',
      '',
    ].join('\n')
  );

  writeFileSync(
    join(BUNDLE, '.dockerignore'),
    ['.git', '.gitignore', 'Dockerfile', '.dockerignore', 'README.md', ''].join('\n')
  );

  writeFileSync(
    join(BUNDLE, 'railway.json'),
    JSON.stringify(
      {
        $schema: 'https://railway.app/railway.schema.json',
        build: { builder: 'DOCKERFILE', dockerfilePath: 'Dockerfile' },
        deploy: { restartPolicyType: 'ON_FAILURE', restartPolicyMaxRetries: 10 },
      },
      null,
      2
    ) + '\n'
  );
}

function commitBundle() {
  log('Committing inside bundle/');
  run('git', ['add', '-A'], { cwd: BUNDLE });

  let committed = false;
  if (hasStagedChanges(BUNDLE)) {
    run('git', ['commit', '-m', `Rebuild bundle (${new Date().toISOString()})`], {
      cwd: BUNDLE,
    });
    committed = true;
  } else {
    console.log('  bundle/ is unchanged — nothing to commit.');
  }

  // Fetch so origin/bundle is current before comparing; a stale ref would
  // make an already-pushed branch look like it still needs pushing.
  if (PUSH) {
    run('git', ['fetch', 'origin', 'bundle'], { cwd: BUNDLE });
    if (needsPush(BUNDLE, 'bundle')) {
      // Submodule checkouts are usually detached, so name the target ref explicitly.
      run('git', ['push', 'origin', 'HEAD:bundle'], { cwd: BUNDLE });
      console.log('  Pushed bundle branch.');
    } else {
      console.log('  origin/bundle already up to date.');
    }
  }
  return committed;
}

function commitPointers() {
  log('Bumping submodule pointers on main');
  run('git', ['add', 'backend', 'frontend', 'cli', 'bundle']);

  let committed = false;
  if (hasStagedChanges(ROOT)) {
    run('git', ['commit', '-m', 'Bump submodule pointers (bundle rebuild)']);
    committed = true;
  } else {
    console.log('  Submodule pointers are unchanged — nothing to commit.');
  }

  if (PUSH) {
    run('git', ['fetch', 'origin', 'main']);
    if (needsPush(ROOT, 'main')) {
      run('git', ['push', 'origin', 'HEAD:main']);
      console.log('  Pushed main.');
    } else {
      console.log('  origin/main already up to date.');
    }
  }
  return committed;
}

function main() {
  updateSubmodules();
  const browserDir = buildFrontend();
  assemble(browserDir);

  const bundleChanged = commitBundle();
  const pointersChanged = commitPointers();

  console.log();
  if (!bundleChanged && !pointersChanged) {
    console.log('✔ Nothing to rebuild — bundle is already up to date.');
  } else if (PUSH) {
    console.log('✔ Bundle rebuilt and pushed.');
  } else {
    console.log('✔ Bundle rebuilt and committed locally.');
    console.log('  Re-run with --push to publish.');
  }
}

try {
  main();
} catch (err) {
  console.error(`\n\u001b[31merror:\u001b[0m ${err.message}`);
  process.exit(1);
}
